}

## CVXPY SOURCE: atoms/affine/transpose.py Transpose.format_labeled.
method(format_labeled, Transpose) <- function(x) {
  lbl <- label(x); if (!is.null(lbl)) return(lbl)
  sprintf("t(%s)", format_labeled(.args(x)[[1L]]))
}
